async () => {
  const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
  const frameEl = () => window.containerRef?.current ?? document.querySelector("iframe");
  const win = () => frameEl().contentWindow;
  const api = () => win().ConfiguratorAPI;
  const round = (n) => +Number(n).toFixed(3);
  const state = async () => {
    const a = api();
    const caps = await a.cabinets.getCapabilities();
    const scope = { apiInstanceId: caps.data.apiInstanceId, compositionId: caps.data.activeCompositionId };
    const s = await a.cabinets.getState(scope);
    const t = await a.countertop.getState();
    return {
      cabinets: (s.data?.cabinets ?? []).map((c) => ({
        id: c.id,
        type: c.definitionId.replace("ULH-", ""),
        w: c.selection?.Width,
        sink: c.selection?.sinkType,
      })),
      top: {
        id: t.productId,
        off: t.offset && { x: round(t.offset.x), y: round(t.offset.y) },
        hosted: t.sink?.hosted === true,
        pending: t.sink?.pending?.status ?? null,
        landing: t.sink?.landing?.status ?? null,
        valid: t.validation?.status,
        reasons: t.validation?.reasons,
        dragEnabled: t.dragEnabled,
        ready: t.readiness,
      },
    };
  };
  const brief = async () => {
    const s = await state();
    return { cabinets: s.cabinets.map((c) => `${c.type}:${c.w}${c.sink ? `[${c.sink}]` : ""}`).join(" "), top: s.top };
  };
  const label = (text) => [...document.querySelectorAll("[class*=_label_]")].find((e) => e.textContent === text);
  const clickItem = (text) => {
    const item = label(text)?.closest("[class*=_item_]");
    if (!item) return false;
    item.click();
    return true;
  };
  const select = (id) => {
    const tool = api().getSelectTool();
    tool.deselectAll();
    tool.setSelectedByName(id, { mode: "replace" });
  };
  const deselect = async () => {
    api().getSelectTool().deselectAll();
    await sleep(500);
  };
  const pick = async (id, text) => {
    for (let attempt = 1; attempt <= 6; attempt++) {
      select(id);
      await sleep(1500);
      for (let i = 0; i < 14; i++) {
        if (clickItem(text)) return true;
        await sleep(150);
      }
    }
    return false;
  };
  const widths = async (id) => {
    for (let attempt = 1; attempt <= 10; attempt++) {
      select(id);
      await sleep(500 + attempt * 200);
      const item = label("Width")?.closest("[class*=_item_]");
      const sub = item?.querySelector("[class*=subWrapper]");
      if (sub) return [...sub.querySelectorAll("[class*=_label_]")].map((e) => e.textContent);
    }
    return null;
  };
  const resize = async (id, text, widthCm) => {
    for (let t = 1; t <= 3; t++) {
      await pick(id, text);
      await sleep(3500);
      if ((await state()).cabinets.some((c) => c.id === id && c.w === widthCm)) {
        await deselect();
        return true;
      }
    }
    await deselect();
    return false;
  };
  const button = (text) => [...document.querySelectorAll("button")].find((b) => (b.textContent ?? "").trim() === text);
  const message = () => {
    const text = document.body.innerText.replace(/\s+/g, " ");
    const at = text.indexOf("Not available for current sink base width");
    return at < 0 ? null : text.slice(at, text.indexOf(".", text.indexOf("minimum", at) + 12) + 1);
  };
  const dismiss = async () => {
    const ok = button("OK");
    if (!ok) return false;
    ok.click();
    await sleep(600);
    return true;
  };
  const overlay = () => {
    const root = document.querySelector("[data-testid=countertop-drag-overlay]");
    if (!root) return null;
    const apply = [...root.querySelectorAll("button")].find((b) => b.textContent === "Apply");
    return {
      status: root.dataset.status,
      alerts: [...root.querySelectorAll("[role=alert],[role=status]")].map((e) => e.textContent),
      applyDisabled: apply ? apply.disabled : null,
    };
  };
  const enterDrag = async (topId) => {
    await pick(topId, "Drag & Drop");
    await sleep(1500);
    const go = button("Continue");
    if (go) {
      go.click();
      await sleep(1800);
    }
    return Boolean(document.querySelector('[data-testid="countertop-move-marker"]'));
  };
  const discard = async () => {
    const x = document.querySelector('[aria-label="Discard countertop changes"]');
    if (!x) return false;
    x.click();
    await sleep(2500);
    return true;
  };
  // The scene reads the mouse from `app.mouse`, which listens on the window of the iframe.
  const fire = (type, x, y) => {
    const w = win();
    const canvas = w.document.querySelector("canvas");
    const init = { bubbles: true, cancelable: true, composed: true, view: w, clientX: x, clientY: y, button: 0, buttons: type === "mouseup" ? 0 : 1 };
    const pointer = { mousedown: "pointerdown", mousemove: "pointermove", mouseup: "pointerup" }[type];
    canvas.dispatchEvent(new w.PointerEvent(pointer, { ...init, pointerId: 1, pointerType: "mouse", isPrimary: true }));
    canvas.dispatchEvent(new w.MouseEvent(type, init));
  };
  const markerPoint = () => {
    const r = document.querySelector('[data-testid="countertop-move-marker"]').getBoundingClientRect();
    const f = frameEl().getBoundingClientRect();
    return { x: r.left + r.width / 2 - f.left, y: r.top + r.height / 2 - f.top };
  };
  const moveTo = async (x, y) => {
    fire("mousemove", x, y);
    await sleep(90);
    return (await state()).top;
  };
  const liftByPointer = async (minYM = 0.15) => {
    const start = markerPoint();
    fire("mousemove", start.x, start.y);
    await sleep(120);
    fire("mousedown", start.x, start.y);
    await sleep(120);
    let y = start.y;
    let top = null;
    for (let i = 0; i < 60; i++) {
      y -= 6;
      top = await moveTo(start.x, y);
      if (top.off.y >= minYM) break;
    }
    fire("mouseup", start.x, y);
    return top;
  };
  const dropBy = async (until, deltas = [0, -6, 6, -12, 12, -18, 18, -24, 24, -30, 30, -40, 40, -50, 50, -60, 60, -80, 80]) => {
    const start = markerPoint();
    fire("mousemove", start.x, start.y);
    await sleep(120);
    fire("mousedown", start.x, start.y);
    await sleep(120);
    let y = start.y;
    let top = null;
    for (let i = 0; i < 80; i++) {
      y += 5;
      top = await moveTo(start.x, y);
      if (top.off.y <= 0.003) break;
    }
    const lowered = { off: top.off, landing: top.landing, overlay: overlay() };
    let hit = until(top);
    let x = start.x;
    if (!hit) {
      for (const d of deltas) {
        x = start.x + d;
        top = await moveTo(x, y);
        if (until(top)) {
          hit = true;
          break;
        }
      }
    }
    await sleep(250);
    const atTarget = { hit, off: top.off, landing: top.landing, pending: top.pending, valid: top.valid, overlay: overlay() };
    window.__c63last = { x, y };
    return { lowered, atTarget };
  };
  const release = () => fire("mouseup", window.__c63last.x, window.__c63last.y);
  const waitFor = async (check, ms) => {
    const end = Date.now() + ms;
    while (Date.now() < end) {
      const value = await check();
      if (value) return value;
      await sleep(250);
    }
    return null;
  };
  window.__c63 = { sleep, state, brief, label, clickItem, select, deselect, pick, widths, resize, button, message, dismiss, overlay, enterDrag, discard, fire, markerPoint, liftByPointer, dropBy, release, waitFor };
  await waitFor(async () => {
    try {
      const s = await state();
      return s.cabinets.length > 0 && s.top.ready === "ready";
    } catch {
      return false;
    }
  }, 45000);
  await sleep(5000);
  const started = button("Get Started");
  if (started) started.click();
  await sleep(600);
  return { walkthroughDismissed: Boolean(started), ...(await brief()) };
}

